const BIMG = new Set(["ammit", "anaksor", "ardent-imugi", "atlas", "baihu-lynx", "blaze-rex", "curie", "dux-mk2", "fafnir", "frozen-dagon-mk2", "harpy", "kaji", "mars", "mauler", "minos", "newton", "noir-shenlou", "retro-revenant", "samjok-mk2", "scorpion", "shell", "spectre", "teth", "typhon", "vulcan"]);
